const response = pm.response.json();

pm.test("Status code should be 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response status should be success", function () {
    pm.expect(response.status).to.eql("success");
});

pm.test("Two unique survey records should exist", function () {
    pm.expect(response.count).to.eql(2);
});

pm.test("Ankit survey should exist", function () {
    const ankit = response.surveys.find(
        survey => survey.device_id === "device-ankit-001"
    );

    pm.expect(ankit).to.exist;
    pm.expect(ankit.local_id).to.eql("School_1");
});

pm.test("Pooja survey should exist", function () {
    const pooja = response.surveys.find(
        survey => survey.device_id === "device-pooja-001"
    );

    pm.expect(pooja).to.exist;
    pm.expect(pooja.local_id).to.eql("School_1");
});

pm.test("Ankit and Pooja should have separate server records", function () {
    const ankit = response.surveys.find(
        survey => survey.device_id === "device-ankit-001"
    );

    const pooja = response.surveys.find(
        survey => survey.device_id === "device-pooja-001"
    );

    pm.expect(ankit.server_id).to.not.eql(pooja.server_id);
});

pm.test("Ankit data should not be overwritten", function () {
    const ankit = response.surveys.find(
        survey => survey.device_id === "device-ankit-001"
    );

    pm.expect(ankit.survey_data.students_count).to.eql(120);
});

pm.test("Pooja data should not overwrite Ankit data", function () {
    const pooja = response.surveys.find(
        survey => survey.device_id === "device-pooja-001"
    );

    pm.expect(pooja.survey_data.students_count).to.eql(125);
});

